import Foundation
@testable import UlaniKit

// Loads shared/vectors/ulani-vectors.json straight from the repo (one source of
// truth, generated by `python -m ulani_epaper.vectors`) and implements its input
// recipes. The packer here is deliberately independent of UlaniKit's.

/// JSON as a Sendable value (JSONSerialization output, converted once).
enum JSON: Sendable, Equatable {
    case null
    case bool(Bool)
    case int(Int)  // the vectors only contain integers
    case string(String)
    case array([JSON])
    case object([String: JSON])

    init(any value: Any) throws {
        switch value {
        case is NSNull:
            self = .null
        case let n as NSNumber:
            if CFGetTypeID(n) == CFBooleanGetTypeID() {
                self = .bool(n.boolValue)
            } else if n.doubleValue == Double(n.intValue) {
                self = .int(n.intValue)
            } else {
                throw VectorError("non-integer number \(n)")
            }
        case let s as String:
            self = .string(s)
        case let a as [Any]:
            self = .array(try a.map { try JSON(any: $0) })
        case let o as [String: Any]:
            self = .object(try o.mapValues { try JSON(any: $0) })
        default:
            throw VectorError("unsupported JSON value \(type(of: value))")
        }
    }

    subscript(key: String) -> JSON? {
        if case .object(let o) = self { return o[key] }
        return nil
    }

    var int: Int? { if case .int(let v) = self { v } else { nil } }
    var bool: Bool? { if case .bool(let v) = self { v } else { nil } }
    var string: String? { if case .string(let v) = self { v } else { nil } }
    var array: [JSON]? { if case .array(let v) = self { v } else { nil } }
    var object: [String: JSON]? { if case .object(let v) = self { v } else { nil } }
    var isNull: Bool { self == .null }
}

struct VectorError: Error, CustomStringConvertible {
    let description: String
    init(_ description: String) { self.description = description }
}

enum Vectors {
    /// <repo>/shared/vectors/ulani-vectors.json: this file's directory, up 4 directories.
    static let url: URL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()  // Tests/UlaniKitTests
        .deletingLastPathComponent()  // Tests
        .deletingLastPathComponent()  // UlaniKit
        .deletingLastPathComponent()  // apple
        .deletingLastPathComponent()  // repo root
        .appendingPathComponent("shared/vectors/ulani-vectors.json")

    private static let loaded = Result<JSON, any Error> {
        try JSON(any: JSONSerialization.jsonObject(with: Data(contentsOf: url)))
    }

    /// The whole vectors file (parsed once per test run).
    static func root() throws -> JSON { try loaded.get() }

    /// Bytes for an input recipe: {"hex"}, {"repeat_hex","count"}, {"bands":true}, {"checker":true}.
    static func input(_ recipe: JSON) throws -> Data {
        if let hex = recipe["hex"]?.string {
            return try fromHex(hex)
        }
        if let hex = recipe["repeat_hex"]?.string, let count = recipe["count"]?.int {
            let unit = try fromHex(hex)
            var out = Data(capacity: unit.count * count)
            for _ in 0..<count { out.append(unit) }
            return out
        }
        if recipe["bands"]?.bool == true { return pack(bandIndices()) }
        if recipe["checker"]?.bool == true { return pack(checkerIndices()) }
        throw VectorError("unknown input recipe \(recipe)")
    }

    static let width = 800, height = 480

    /// Palette index of column x in the 7-band frame.
    static func bandIndex(x: Int) -> UInt8 { UInt8(min(x / 114, 6)) }

    /// Palette index at (x, y) of the asymmetric checker frame.
    static func checkerIndex(x: Int, y: Int) -> UInt8 { UInt8(((x / 115) + (y / 69)) % 7) }

    /// 384 000 indices, row-major from the top-left.
    static func bandIndices() -> [UInt8] {
        let row = (0..<width).map { bandIndex(x: $0) }
        return Array((0..<height).map { _ in row }.joined())
    }

    static func checkerIndices() -> [UInt8] {
        var out = [UInt8]()
        out.reserveCapacity(width * height)
        for y in 0..<height {
            for x in 0..<width { out.append(checkerIndex(x: x, y: y)) }
        }
        return out
    }

    /// Test-side packer: two pixels per byte, first pixel in the high nibble, odd count padded with 0.
    static func pack(_ indices: [UInt8]) -> Data {
        var out = Data(capacity: (indices.count + 1) / 2)
        var i = 0
        while i < indices.count {
            let low = i + 1 < indices.count ? indices[i + 1] : 0
            out.append(indices[i] << 4 | low)
            i += 2
        }
        return out
    }
}

/// Lower-case hex without separators -> bytes.
func fromHex(_ hex: String) throws -> Data {
    let chars = Array(hex.utf8)
    guard chars.count % 2 == 0 else { throw VectorError("odd-length hex \(hex)") }
    var out = Data(capacity: chars.count / 2)
    var i = 0
    while i < chars.count {
        guard let byte = UInt8(String(decoding: chars[i...i + 1], as: UTF8.self), radix: 16) else {
            throw VectorError("bad hex \(hex)")
        }
        out.append(byte)
        i += 2
    }
    return out
}

/// Bytes -> lower-case hex without separators.
func toHex(_ data: Data) -> String {
    data.map { byte in
        let s = String(byte, radix: 16)
        return byte < 0x10 ? "0" + s : s
    }.joined()
}

/// Zero-padded lower-case hex of an integer, e.g. hexNumber(0x31c3, digits: 4) == "31c3".
func hexNumber(_ value: some BinaryInteger, digits: Int) -> String {
    let s = String(value, radix: 16)
    return String(repeating: "0", count: max(0, digits - s.count)) + s
}

/// The message of the UlaniError.protocolError that `body` throws; nil if it throws
/// nothing or anything else.
func protocolErrorMessage(_ body: () throws -> Void) -> String? {
    do {
        try body()
        return nil
    } catch UlaniError.protocolError(let message) {
        return message
    } catch {
        return nil
    }
}
